functions.template:
{%- set d = http('https://api.open-meteo.com/v1/forecast?latitude=${latitude}&longitude=${longitude}&current=temperature_2m,weather_code,wind_speed_10m,relative_humidity_2m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max&timezone=${timezone}&forecast_days=4&models=icon_seamless') -%}
{%- macro wt(c) -%}{%- if c == 0 %}klar{%- elif c == 1 %}überwiegend sonnig{%- elif c == 2 %}teils wolkig{%- elif c == 3 %}bedeckt{%- elif c in [45,48] %}Nebel{%- elif c in [51,53,55] %}Nieselregen{%- elif c in [56,57] %}gefriender Nieselregen{%- elif c in [61,63] %}Regen{%- elif c == 65 %}starker Regen{%- elif c in [66,67] %}gefriender Regen{%- elif c in [71,73] %}Schneefall{%- elif c == 75 %}starker Schneefall{%- elif c in [80,81] %}Schauer{%- elif c == 82 %}heftige Schauer{%- elif c in [85,86] %}Schneeschauer{%- elif c == 95 %}Gewitter{%- elif c in [96,99] %}Gewitter mit Hagel{%- else %}wechselhaft{%- endif -%}{%- endmacro -%}
{%- macro deg(v) -%}{{ (v or 0) | round(0) | replace('.', ',') }}{%- endmacro -%}
{%- if d and d.current -%}
Aktuell {{ deg(d.current.temperature_2m) }} Grad, {{ wt(d.current.weather_code) }}, Wind {{ deg(d.current.wind_speed_10m) }} km/h.
Heute {{ wt(d.daily.weather_code[0]) }}, {{ deg(d.daily.temperature_2m_max[0]) }} Grad tagsüber, {{ deg(d.daily.temperature_2m_min[0]) }} Grad nachts, Regenrisiko {{ deg(d.daily.precipitation_probability_max[0]) }} Prozent.
Morgen {{ wt(d.daily.weather_code[1]) }}, {{ deg(d.daily.temperature_2m_max[1]) }} Grad tagsüber, {{ deg(d.daily.temperature_2m_min[1]) }} Grad nachts, Regenrisiko {{ deg(d.daily.precipitation_probability_max[1]) }} Prozent.
Übermorgen {{ wt(d.daily.weather_code[2]) }}, {{ deg(d.daily.temperature_2m_max[2]) }} Grad tagsüber, {{ deg(d.daily.temperature_2m_min[2]) }} Grad nachts, Regenrisiko {{ deg(d.daily.precipitation_probability_max[2]) }} Prozent.
{%- else -%}
Ich konnte das Wetter gerade nicht abrufen.
{%- endif -%}
